def parse_pair(txt, tag, h, w):
    ih = f"Demo pair {tag} input ({h}x{w}):"
    oh = f"Demo pair {tag} output ({h}x{w}):"
    def gr(header):
        i = txt.index(header); seg = txt[i+len(header):]
        rows=[]
        for line in seg.strip().split('\n'):
            if not line or not line[0].isdigit(): break
            rows.append([int(x) for x in line.split()])
        return rows
    return gr(ih), gr(oh)
