def best_periods(g, top=8):
    R,C=len(g),len(g[0]); res=[]
    import itertools
    for dr in range(-R+1,R):
        for dc in range(-C+1,C):
            if dr==0 and dc==0: continue
            tot=match=0
            for r in range(R):
                for c in range(C):
                    r2,c2=r+dr,c+dc
                    if 0<=r2<R and 0<=c2<C:
                        tot+=1; match+= (g[r][c]==g[r2][c2])
