from collections import Counter
def feats(g, o, diffset, bg):
    col, cells = o
    S=set(cells)
    # 8-neighbors outside object
    nb=set()
    for r,c in S:
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                r2,c2=r+dr,c+dc
                if (r2,c2) not in S and 0<=r2<len(g) and 0<=c2<len(g[0]):
                    nb.add((r2,c2))
    touch_edge = any(r==0 or c==0 or r==len(g)-1 or c==len(g[0])-1 for r,c in S)
    nbr_colors = Counter(g[r][c] for r,c in nb if g[r][c]!=bg and (r,c) not in S)
    ch = bool(S & diffset)
    return dict(col=col,size=len(cells),changed=ch,touch_edge=touch_edge,
                nbcolors=dict(nbr_colors), nobj=len(nbr_colors))

